      lbl(S, 'l2', 19.0, 4.4, ['require.cache에서 지우면 다시 실행돼 새 인스턴스가 생겨요 · 옛 참조는 옛 상태를 계속 봐요', 'clearing require.cache re-runs it as a new instance; old references keep old state'], 'w', 2, { w: 12.4 });
      mono(S, 'r3', 19.0, 5.9, ['y sees x = {"loaded":false}', 'Warning: … inside circular dependency'], 3, { w: 12.4, dy: .55, c: 'ndx-r' });
