      lbl(S, 'm1', 1, 7.0, ['캐시 키는 해석된 파일 경로라서, 다른 경로로 해석되면(심볼릭 링크, 중복 설치) 두 벌이 생겨요', 'the cache key is the resolved file path, so a module reached via different paths (symlinks, duplicate installs) loads twice'], 'a', 1, { w: 16.0 });
