    fin: [['모듈은 한 번만 실행되고 캐시돼요', 'modules run once and are cached', 'ndx-xs ndx-a'], ['모듈 상태 = 싱글턴', 'module state is a singleton'], ['순환 참조는 미완성 exports를 줘요', 'cycles hand out unfinished exports']],
