      lbl(S, 'l4', 19.0, 8.8, ['pipeline은 이 일을 자동으로 해요 · 시간은 셋 다 같아서, 배압은 속도 손해 없이 메모리만 지켜요', 'pipeline does this for you; all three took the same time, so backpressure only saves memory'], 'g', 4, { w: 12.4 });
