function sWorkerN() {
  return CW('node-worker', {
    code: ['new Worker(__filename, { workerData: 38 })', ['// 메인 스레드 fib(38) ×2: 752ms', '// main thread, fib(38) ×2: 752 ms'], ['// 워커 2개: 430ms, 루프 지연 3ms', '// 2 workers: 430 ms, loop lag 3 ms'], ['w.postMessage(buf, [buf])   // 전송 8ms', 'w.postMessage(buf, [buf])   // transfer 8 ms'], ['Atomics.add(ia, 0, 1)       // 공유 메모리', 'Atomics.add(ia, 0, 1)       // shared memory']],
    hl: [[1, 1, 'danger'], [0, 3, 'ok'], [3, 1, 'warn'], [4, 1, 'accent']],
    draw: (S) => {
      rbars(S, 'b1', .5, [['main ×2', 6.0, 'danger', '752 ms']], 1);
      lbl(S, 'l1', 19.0, 1.2, ['CPU 계산을 메인 스레드에서 하면 그동안 루프가 멈춰요 · fib(38) 두 번에 752ms', 'CPU work on the main thread stops the loop meanwhile: 752 ms for fib(38) twice'], 'r', 1, { w: 12.4 });
      rbars(S, 'b2', 2.7, [['2 workers', 3.43, 'ok', '430 ms']], 2); T(S, 'lg', 19.0, 3.3, 'main loop lag: 3 ms', 'cz-mono ndx-tiny ndx-g', 2, { w: 12.4 });
      lbl(S, 'l2', 19.0, 3.9, ['워커 스레드는 별도의 V8 인스턴스에서 돌아요 · 코어 2개를 함께 써 430ms, 메인 루프는 3ms만 밀렸어요', 'workers run in own V8 instances: 430 ms on 2 cores, main loop slipped 3 ms'], 'g', 2, { w: 12.4 });
      rbars(S, 'b3', 5.4, [['clone', 6.0, 'ink-3', '210 ms'], ['transfer', .23, 'ok', '8 ms']], 3);
      lbl(S, 'l3', 19.0, 6.6, ['100MB를 그냥 보내면 복사(210ms), 전송 목록에 넣으면 소유권만 넘겨요(8ms) · 보낸 쪽은 길이 0', 'posting 100 MB copies it (210 ms); transferring moves it (8 ms), length 0 left'], 'w', 3, { w: 12.4 });
      mono(S, 'at', 19.0, 8.1, nbs(['Atomics.add  → 2,000,000', 'a[0]++       → 1,479,778']), 4, { w: 12.4, dy: .55, c: 'ndx-a' });
      lbl(S, 'l4', 19.0, 9.3, ['SharedArrayBuffer는 진짜 공유 메모리라 경쟁이 생겨요 · Atomics 없이 더하자 52만 번이 사라졌어요', 'a SharedArrayBuffer is truly shared, so races happen: without Atomics, 520,000 increments vanished'], 'a', 4, { w: 12.4 });
      lbl(S, 'm2', 1, 7.0, ['워커 하나를 띄우는 데 42ms가 걸렸어요 · 요청마다 만들지 말고 워커 풀을 둬요', 'starting a worker took 42 ms, so keep a pool of workers rather than one per request'], 'g', 2, { w: 16.0 });
    },
    notes: [['fib(38)처럼 CPU만 쓰는 계산을 메인 스레드에서 두 번 하자 752ms가 걸렸고, 그동안 이벤트 루프는 완전히 멈췄어요 · 비동기 함수로 감싸도 계산 자체는 메인 스레드에서 돌기 때문에 소용없어요', 'running a purely CPU-bound computation such as fib(38) twice on the main thread took 752 ms, during which the event loop stopped completely, and wrapping it in an async function does not help because the computation itself still runs on the main thread'], ['worker_threads의 Worker는 같은 프로세스 안에서 별도의 V8 인스턴스와 이벤트 루프를 가진 스레드를 만들어요 · 워커 2개에 하나씩 맡기자 코어 2개를 함께 써서 430ms에 끝났고, 그동안 메인 루프는 최대 3ms만 밀렸어요 · 워커 하나를 띄우는 데 42ms가 들어서 보통 워커 풀을 둬요', 'a Worker from worker_threads creates a thread inside the same process with its own V8 instance and event loop, and giving one computation to each of 2 workers used both cores, finishing in 430 ms while the main loop was delayed by at most 3 ms; starting a worker cost 42 ms, so a pool of workers is the usual approach'], ['워커와는 메시지로 데이터를 주고받고, 기본은 구조화된 복제라서 복사가 일어나요 · 100MB ArrayBuffer를 그냥 보내자 210ms였고, 두 번째 인자인 전송 목록에 넣자 메모리 소유권만 넘겨 8ms였어요 · 대신 보낸 쪽의 버퍼는 길이가 0이 되어 더는 쓸 수 없어요', 'data is exchanged with workers through messages, by structured cloning by default, which copies: posting a 100 MB ArrayBuffer took 210 ms, while listing it in the transfer list, the second argument, handed over ownership of the memory in 8 ms, after which the sender’s buffer had length 0 and could no longer be used'], ['SharedArrayBuffer는 여러 워커가 진짜로 같은 메모리를 봐요 · 두 워커가 같은 칸을 100만 번씩 a[0]++로 올리자 2,000,000이 아니라 1,479,778이 됐어요 · 읽고 더하고 쓰는 사이에 서로의 결과를 덮어써서예요 · Atomics.add를 쓰자 정확히 2,000,000이었어요', 'with a SharedArrayBuffer, several workers truly see the same memory, so two workers each incrementing the same slot a million times with a[0]++ ended at 1,479,778 rather than 2,000,000, because each overwrote the other’s results between reading, adding and writing, while Atomics.add gave exactly 2,000,000']],
    fin: [['CPU 계산은 워커 스레드로', 'move CPU work to worker threads', 'ndx-xs ndx-a'], ['큰 데이터는 복사 대신 전송', 'transfer large data instead of copying'], ['공유 메모리는 Atomics로', 'use Atomics on shared memory']],
    caps: [['메인 스레드의 계산', 'Computing on the main thread'], ['워커 스레드', 'Worker threads'], ['복제와 전송', 'Cloning and transfer'], ['공유 메모리', 'Shared memory'], ['워커 스레드', 'Worker threads']]
  });
}

