    caps: [['run과 getStore', 'run and getStore'], ['뒤섞여도 정확하게', 'Correct even out of order'], ['전역 변수의 함정', 'The global variable trap'], ['비용', 'The cost'], ['AsyncLocalStorage', 'AsyncLocalStorage']]
